#!/usr/bin/env bash
# Adaptive Bash frontend -- the Readline / Bash-programmable-completion adapter.
#
# Generated by `adaptive init bash`; do not edit -- regenerate instead.
#
# ---------------------------------------------------------------------------
# HOW GHOST TEXT WORKS HERE, AND WHY IT DIFFERS FROM ZSH
# ---------------------------------------------------------------------------
# Zsh has ZLE, which offers POSTDISPLAY: text drawn after the cursor that is
# display-only, so Enter runs what you typed and the ghost is never executed.
#
# Readline has no equivalent. It renders exactly READLINE_LINE and nothing
# else, so a ghost painted from outside is erased by the next repaint
# (verified: Readline repaints with CR + erase-to-EOL). This frontend keeps the
# suggestion *inside* the line buffer instead:
#
#     READLINE_LINE  = <what you typed><the suggestion>
#     READLINE_POINT = <length of what you typed>
#
# The cursor sits on the boundary, so the suggestion is visible and every
# Readline feature (wrapping, resize, history, cursor keys) keeps working,
# because it is still just a line of text. Accepting is moving to the end;
# rejecting is dropping the tail.
#
# Three consequences are deliberate:
#   * The ghost is NOT dimmed. Readline renders ANSI literally -- injecting
#     $'\e[2m' shows the characters ^[[2m -- so styling it would mean replacing
#     the line editor, which is out of scope for a completion integration.
#   * Enter must never run a suggestion, so C-m/C-j are pointed at
#     `_adaptive_enter` only while a ghost is on screen (see `_adaptive_arm`).
#   * Cursor movement left of the boundary drops the ghost first, so the
#     suggestion can never be spliced into the middle of real text.
#
# KEYS (all overridable by exporting the matching ADAPTIVE_* before sourcing)
#   Right / End        accept the whole suggestion
#   Ctrl-Right         accept one word of it
#   Ctrl-X             discard the suggestion
#   Shift-Tab          walk the candidate list backwards
#   Tab                normal completion (the engine, then Bash's own rules)

: "${ADAPTIVE_GHOST_TEXT:=1}"
: "${ADAPTIVE_GHOST_ACCEPT_KEY:=$'\e[C'}"
: "${ADAPTIVE_GHOST_WORD_KEY:=$'\e[1;5C'}"
: "${ADAPTIVE_GHOST_REJECT_KEY:=$'\C-x'}"
: "${ADAPTIVE_BROWSE_KEY:=$'\e[Z'}"
: "${ADAPTIVE_TAB_KEY:=$'\C-i'}"
: "${ADAPTIVE_TAB_DROP_KEY:=$'\C-x\C-q'}"
: "${ADAPTIVE_BROWSE_MARK_KEY:=$'\C-x\C-z'}"

[[ -n ${ADAPTIVE_BIN_PATH:-} ]] || _adaptive_find_bin || return 0
(( BASH_VERSINFO[0] >= 4 )) || return 0

_adaptive_init_paths

# ---------------------------------------------------------------------------
# turning a key into Readline syntax
# ---------------------------------------------------------------------------
# Keys are configured as ordinary Bash literals (so `export ADAPTIVE_..._KEY`
# can use $'\e[C' and friends), but Readline's `bind` wants its own escape
# text. Converting in one place keeps every binding below correct and quoting
# is handled by printf rather than by nested shell quotes.
_adaptive_rl_escape() {
  local s=$1 out= i c
  for (( i = 0; i < ${#s}; i++ )); do
    c=${s:i:1}
    case $c in
      $'\C-?') out+='\C-?' ;;
      $'\C-@') out+='\C-@' ;;
      $'\C-A') out+='\C-A' ;;
      $'\C-B') out+='\C-B' ;;
      $'\C-C') out+='\C-C' ;;
      $'\C-D') out+='\C-D' ;;
      $'\C-E') out+='\C-E' ;;
      $'\C-F') out+='\C-F' ;;
      $'\C-G') out+='\C-G' ;;
      $'\C-H') out+='\C-H' ;;
      $'\C-K') out+='\C-K' ;;
      $'\C-L') out+='\C-L' ;;
      $'\C-N') out+='\C-N' ;;
      $'\C-P') out+='\C-P' ;;
      $'\C-Q') out+='\C-Q' ;;
      $'\C-R') out+='\C-R' ;;
      $'\C-S') out+='\C-S' ;;
      $'\C-T') out+='\C-T' ;;
      $'\C-U') out+='\C-U' ;;
      $'\C-V') out+='\C-V' ;;
      $'\C-W') out+='\C-W' ;;
      $'\C-X') out+='\C-X' ;;
      $'\C-Y') out+='\C-Y' ;;
      $'\e')   out+='\e' ;;
      $'\t')   out+='\t' ;;
      $'\n')   out+='\n' ;;
      *)       out+=$c ;;
    esac
  done
  _ADAPTIVE_ESCAPED=$out
}

# `bind -x '"<key>": <function>'`
_adaptive_bindx() {
  _adaptive_rl_escape "$1"
  _ADAPTIVE_BINDING="\"$_ADAPTIVE_ESCAPED\": $2"
}

# `bind '"<key>": <readline command or macro>'`
_adaptive_bindcmd() {
  _adaptive_rl_escape "$1"
  _ADAPTIVE_BINDING="\"$_ADAPTIVE_ESCAPED\": $2"
}

# ---------------------------------------------------------------------------
# reading and editing the line
# ---------------------------------------------------------------------------

# The line the user actually typed: everything left of the cursor.
_adaptive_typed() { _ADAPTIVE_TYPED="${READLINE_LINE:0:$READLINE_POINT}"; }

# The partial word under the cursor. Empty right after a space, which is where
# the engine predicts a whole next token ("git " -> "status").
_adaptive_current_word() {
  local before=${READLINE_LINE:0:$READLINE_POINT}
  _ADAPTIVE_WORD=${before##*[[:space:]]}
}

# Remove a planted ghost, but only when the tail really is the ghost we put
# there. Text the user has moved the cursor into is never touched.
_adaptive_drop_ghost() {
  if [[ -n ${_ADAPTIVE_GHOST:-} \
        && ${READLINE_LINE:READLINE_POINT} == "$_ADAPTIVE_GHOST" ]]; then
    READLINE_LINE=${READLINE_LINE:0:$READLINE_POINT}
  fi
  _ADAPTIVE_GHOST=
  _ADAPTIVE_GHOST_VALUE=
  _adaptive_arm
}

# Recompute the suggestion for the current line.
#
# Only ever plants one when the cursor is at the end of the line: a suggestion
# you cannot see is one you cannot act on, and the Zsh frontend holds the same
# rule.
_adaptive_refresh() {
  _ADAPTIVE_GHOST=
  _ADAPTIVE_GHOST_VALUE=
  _adaptive_arm
  # Re-arm the Tab macro on every edit: its first step points Tab at plain
  # `complete` for the keystroke that follows, so this restores it.
  _adaptive_arm_tab
  _adaptive_arm_browse
  (( READLINE_POINT == ${#READLINE_LINE} )) || return 0
  [[ ${ADAPTIVE_GHOST_TEXT} == 1 ]] || return 0
  (( ${#_ADAPTIVE_SUPPRESS} )) && return 0

  local typed word suggestion
  _adaptive_typed; typed=$_ADAPTIVE_TYPED
  [[ -n $typed ]] || return 0
  _adaptive_current_word; word=$_ADAPTIVE_WORD

  _adaptive_cache_load || return 0
  _adaptive_cache_best "$word" || return 0
  suggestion=$_ADAPTIVE_BEST

  # Only ever a clean extension of what is already typed.
  [[ $suggestion == "$word"* ]] || return 0
  (( ${#suggestion} > ${#word} )) || return 0

  _ADAPTIVE_GHOST_VALUE=$suggestion
  _ADAPTIVE_GHOST=${suggestion:${#word}}
  READLINE_LINE="$typed$_ADAPTIVE_GHOST"
  READLINE_POINT=${#typed}
  _adaptive_arm
  return 0
}

# ---------------------------------------------------------------------------
# accept / reject
# ---------------------------------------------------------------------------

# Accept everything on the line and step past it with a space, so the next
# token starts fresh.
_adaptive_accept() {
  if [[ -n ${_ADAPTIVE_GHOST:-} ]]; then
    _adaptive_feedback accept "$_ADAPTIVE_GHOST_VALUE" "${ADAPTIVE_Q_CONTEXT:-}"
    # Step past the accepted text with a space, and leave the cursor after it,
    # so the next word is typed in the right place.
    READLINE_LINE+=$' '
    READLINE_POINT=${#READLINE_LINE}
  else
    # No suggestion: behave exactly like Right normally would.
    (( READLINE_POINT < ${#READLINE_LINE} )) || return 0
    READLINE_POINT=$(( READLINE_POINT + 1 ))
  fi
  _ADAPTIVE_GHOST=
  _ADAPTIVE_GHOST_VALUE=
  _adaptive_arm
}

# Accept, from the End key. With no suggestion this must stay exactly
# Readline's end-of-line, so it cannot simply reuse `_adaptive_accept`, whose
# no-suggestion branch moves one character (Right's behaviour).
_adaptive_accept_end() {
  if [[ -n ${_ADAPTIVE_GHOST:-} ]]; then
    _adaptive_feedback accept "$_ADAPTIVE_GHOST_VALUE" "${ADAPTIVE_Q_CONTEXT:-}"
    READLINE_LINE+=$' '
    READLINE_POINT=${#READLINE_LINE}
    _ADAPTIVE_GHOST=
    _ADAPTIVE_GHOST_VALUE=
    _adaptive_arm
    return 0
  fi
  READLINE_POINT=${#READLINE_LINE}
  return 0
}

# Accept the first word of the suggestion only.
_adaptive_accept_word() {
  [[ -n ${_ADAPTIVE_GHOST:-} ]] || return 1
  local typed=${READLINE_LINE:0:$READLINE_POINT} ghost=$_ADAPTIVE_GHOST
  local i word
  for (( i = 0; i < ${#ghost}; i++ )); do
    [[ ${ghost:i:1} == [[:space:]] ]] && break
  done
  word=${ghost:0:i}
  READLINE_LINE="$typed$word "
  READLINE_POINT=${#READLINE_LINE}
  _ADAPTIVE_GHOST=
  _ADAPTIVE_GHOST_VALUE=
  _adaptive_arm
  return 0
}

# ---------------------------------------------------------------------------
# typing and cursor movement
# ---------------------------------------------------------------------------

# Insert one printable character. The character arrives as $1 because a
# `bind -x` handler cannot read it from the input stream.
_adaptive_self_insert() {
  local c=$1 tail typed
  tail=${READLINE_LINE:READLINE_POINT}
  typed=${READLINE_LINE:0:$READLINE_POINT}
  # Drop a planted ghost first, so the new character extends what the user
  # typed rather than the suggestion.
  if [[ -n ${_ADAPTIVE_GHOST:-} && $tail == "$_ADAPTIVE_GHOST" ]]; then
    tail=
  fi
  typed+=$c
  READLINE_LINE="$typed$tail"
  READLINE_POINT=${#typed}
  _ADAPTIVE_GHOST=
  _ADAPTIVE_GHOST_VALUE=
  _adaptive_refresh
}

_adaptive_backspace() {
  _adaptive_drop_ghost
  (( READLINE_POINT > 0 )) || return 0
  local head=${READLINE_LINE:0:$READLINE_POINT} tail=${READLINE_LINE:READLINE_POINT}
  READLINE_LINE=${head:0:${#head}-1}$tail
  READLINE_POINT=$(( READLINE_POINT - 1 ))
  _adaptive_refresh
}

_adaptive_kill_to_start() {
  _adaptive_drop_ghost
  READLINE_LINE=${READLINE_LINE:READLINE_POINT}
  READLINE_POINT=0
  _adaptive_refresh
}

_adaptive_kill_to_end() {
  _adaptive_drop_ghost
  READLINE_LINE=${READLINE_LINE:0:$READLINE_POINT}
  _adaptive_refresh
}

# Cursor movement: drop any suggestion first so the user can never end up
# typing in the middle of one, then move as usual.
_adaptive_move_left() {
  _adaptive_drop_ghost
  (( READLINE_POINT > 0 )) && READLINE_POINT=$(( READLINE_POINT - 1 ))
  return 0
}

_adaptive_move_start() {
  _adaptive_drop_ghost
  READLINE_POINT=0
  return 0
}

_adaptive_discard() { _adaptive_drop_ghost; }

_adaptive_toggle_suppress() {
  if (( ${#_ADAPTIVE_SUPPRESS} )); then
    _ADAPTIVE_SUPPRESS=
    _adaptive_refresh
  else
    _ADAPTIVE_SUPPRESS=1
    _adaptive_drop_ghost
  fi
}

# ---------------------------------------------------------------------------
# Enter
# ---------------------------------------------------------------------------

# Point the accept keys at `_adaptive_enter` while a suggestion is on screen,
# and back at Bash's own accept-line the moment it is not.
#
# Two different binding mechanisms are needed. `_adaptive_enter` is a shell
# function, so it needs `bind -x`; `accept-line` is a Readline command, not a
# shell function, so `bind -x` would fail with "command not found" and it must
# be bound the ordinary way.
_adaptive_arm() {
  if [[ -n ${_ADAPTIVE_GHOST:-} ]]; then
    builtin bind -x '"\C-m": _adaptive_enter' 2>/dev/null || true
    builtin bind -x '"\C-j": _adaptive_enter' 2>/dev/null || true
    builtin bind -x '"\e[13~": _adaptive_enter' 2>/dev/null || true
  else
    builtin bind '"\C-m": accept-line' 2>/dev/null || true
    builtin bind '"\C-j": accept-line' 2>/dev/null || true
    builtin bind '"\e[13~": accept-line' 2>/dev/null || true
  fi
}

# Run exactly what was typed, never the suggestion.
#
# Readline offers no way to call accept-line from inside a `bind -x` handler:
# appending $'\n' to READLINE_LINE does not accept the line, and rebinding
# inside the handler only takes effect on the *next* keypress. So the binding
# itself is swapped by `_adaptive_arm`, and this handler is only ever installed
# when there is a ghost to protect.
#
# Everything else -- multi-line continuation via PS2, history expansion, quoted
# newlines -- stays on Bash's own code path, untouched.
_adaptive_enter() {
  local typed
  _adaptive_typed; typed=$_ADAPTIVE_TYPED
  READLINE_LINE=
  READLINE_POINT=0
  _ADAPTIVE_GHOST=
  _ADAPTIVE_GHOST_VALUE=
  _adaptive_arm
  _adaptive_history_record "$typed"
  builtin history -s "$typed"
  eval "$typed"
  return 0
}

# Tab, step one: drop any suggestion, then hand the key to Readline's own
# `complete`.
#
# The suggestion sits inside READLINE_LINE, so while it is there Readline's
# completion region extends across it and Tab would splice a completion into
# the suggestion ("git pu" + ghost "sh" became "git pushsh"). Removing the
# suggestion first keeps completion operating on exactly what was typed.
#
# This has to be a key macro rather than a `bind -x` handler, because only
# Readline's `complete` both runs a completion function and renders the
# matches. The macro cannot contain Tab itself -- that would re-enter the
# macro -- so the handler re-points Tab at plain `complete` for the keystroke
# that follows, and `_adaptive_refresh` puts the macro back on the next
# keystroke.
_adaptive_pre_complete() {
  _adaptive_drop_ghost
  # This keystroke is the one that actually completes, so point both Tab and
  # Shift-Tab at the real Readline commands; the macros are re-armed on the
  # next edit.
  _adaptive_bindcmd "$ADAPTIVE_TAB_KEY" 'complete'
  builtin bind "$_ADAPTIVE_BINDING" 2>/dev/null || true
  _adaptive_bindcmd "$ADAPTIVE_BROWSE_KEY" "${_ADAPTIVE_BROWSE_CMD:-complete}"
  builtin bind "$_ADAPTIVE_BINDING" 2>/dev/null || true
}

_adaptive_arm_tab() {
  local drop
  _adaptive_rl_escape "$ADAPTIVE_TAB_DROP_KEY"
  drop=$_ADAPTIVE_ESCAPED
  _adaptive_bindcmd "$ADAPTIVE_TAB_KEY" "\"$drop\\t\""
  builtin bind "$_ADAPTIVE_BINDING" 2>/dev/null || true
}

# Shift-Tab.
#
# Readline has done this properly since 8.0: `menu-complete-backward` walks the
# matches of whatever completion functions are registered -- for us, the
# engine's candidates, in reverse. That is far better than reversing COMPREPLY
# by hand, because it also handles the "a candidate is already inserted, move
# to the previous one" case that a per-invocation reversal cannot see.
#
# `bind` reports success even for a function name it does not know, so support
# is detected the only reliable way: `bind -p` lists every function Readline
# knows about, including unbound ones. On older Readline the key falls back to
# plain `complete`, which still completes -- just forwards.
_adaptive_detect_browse() {
  # `bind` reports success even for a function name it does not know, so
  # support is detected the only reliable way: `bind -p` lists every function
  # Readline knows about, including unbound ones.
  if builtin bind -p 2>/dev/null | grep -q 'menu-complete-backward'; then
    _ADAPTIVE_BROWSE_CMD='menu-complete-backward'
  else
    _ADAPTIVE_BROWSE_CMD='complete'
  fi
}

# Shift-Tab goes through the same drop-the-suggestion macro as Tab: while a
# suggestion is on the line it sits inside the buffer, and Readline's
# completion region would run straight across it, so nothing would complete.
# The macro's tail re-sends the Shift-Tab sequence, which by then has been
# re-pointed at the real command.
_adaptive_arm_browse() {
  local mark browse
  _adaptive_rl_escape "$ADAPTIVE_BROWSE_MARK_KEY"; mark=$_ADAPTIVE_ESCAPED
  _adaptive_rl_escape "$ADAPTIVE_BROWSE_KEY";       browse=$_ADAPTIVE_ESCAPED
  _adaptive_bindcmd "$ADAPTIVE_BROWSE_KEY" "\"$mark$browse\""
  builtin bind "$_ADAPTIVE_BINDING" 2>/dev/null || true
}

# ---------------------------------------------------------------------------
# programmable completion
# ---------------------------------------------------------------------------

# The buffer and cursor exactly as Readline sees them, minus any suggestion.
#
# The suggestion lives inside READLINE_LINE, so COMP_LINE arrives carrying it;
# the engine must never be asked about a position the user has not actually
# typed, or Tab would complete the suggestion instead of the word.
_adaptive_complete_buffer() {
  local buf=${COMP_LINE:-${READLINE_LINE:-}}
  if [[ -n ${_ADAPTIVE_GHOST:-} && $buf == *"$_ADAPTIVE_GHOST" ]]; then
    buf=${buf%"$_ADAPTIVE_GHOST"}
  fi
  printf '%s' "$buf"
}

# Matching cursor, clamped to the stripped buffer.
_adaptive_complete_point() {
  local point=${COMP_POINT:-0}
  if [[ -n ${_ADAPTIVE_GHOST:-} && ${COMP_LINE:-} == *"$_ADAPTIVE_GHOST" ]]; then
    point=$(( point - ${#_ADAPTIVE_GHOST} ))
    (( point < 0 )) && point=0
  fi
  printf '%s' "$point"
}

# Tab. Answers with the engine's candidates for the current position and falls
# back to Bash's own completion (return 124) whenever the engine has nothing
# useful, so filesystem completion and command-specific functions from
# bash-completion keep working exactly as they did before.
_adaptive_complete() {
  local cur=${COMP_WORDS[${COMP_CWORD:-0}]:-}
  local out
  COMPREPLY=()
  out=$(_adaptive_query "$(_adaptive_complete_buffer)" "$(_adaptive_complete_point)" 1) || return 124
  [[ -n $out ]] || return 124
  _adaptive_parse <<<"$out"

  local v
  for v in ${ADAPTIVE_Q_VALUES[@]+"${ADAPTIVE_Q_VALUES[@]}"}; do
    [[ -n $v ]] || continue
    [[ -n $cur && $v != "$cur"* ]] && continue
    COMPREPLY+=("$v")
  done

  # Shift-Tab asked to walk backwards, so present the ranking in reverse:
  # Readline consumes matches in list order, so reversing is what makes the
  # gesture move the other way. The flag is one-shot.
  if (( ${#_ADAPTIVE_REVERSE} )); then
    _ADAPTIVE_REVERSE=
    local -a rev=()
    for (( v = ${#COMPREPLY[@]} - 1; v >= 0; v-- )); do rev+=("${COMPREPLY[v]}"); done
    COMPREPLY=(${rev[@]+"${rev[@]}"})
  fi

  _adaptive_log "complete cur=[$cur] line=[${COMP_LINE:-}] -> ${#COMPREPLY[@]} matches: ${COMPREPLY[*]:-none}"
  (( ${#COMPREPLY[@]} )) || return 124
  # One unambiguous answer: tell the engine it was accepted, so ranking learns
  # that this was the right thing at this position.
  if (( ${#COMPREPLY[@]} == 1 )) && [[ -n ${ADAPTIVE_Q_CONTEXT:-} ]]; then
    _adaptive_feedback accept "${COMPREPLY[0]}" "$ADAPTIVE_Q_CONTEXT"
  fi
  return 0
}

# Shift-Tab, invoked directly (rather than through the marker macro). Kept as
# a named entry point so the behaviour can be exercised without a terminal.
_adaptive_complete_backward() {
  _ADAPTIVE_REVERSE=1
  _adaptive_complete
}

# ---------------------------------------------------------------------------
# installation
# ---------------------------------------------------------------------------

# Session state, explicitly re-initialised rather than unset: sourcing this
# file inside a `set -u` shell (which plenty of people run) must not fail on an
# unset variable, and re-sourcing should start from a clean slate.
: "${_ADAPTIVE_GHOST:=}" "${_ADAPTIVE_GHOST_VALUE:=}" "${_ADAPTIVE_SUPPRESS:=}"
: "${_ADAPTIVE_PREV_CMD:=}" "${_ADAPTIVE_REVERSE:=}" "${_ADAPTIVE_BROWSE_CMD:=}"
: "${_ADAPTIVE_CACHE_KEY:=}" "${_ADAPTIVE_SEEN_HISTORY:=}"
_ADAPTIVE_CACHE_VALUES=()
_ADAPTIVE_CACHE_DISPLAYS=()

# Bind every printable ASCII character.
#
# Readline has no "on any character" hook: binding the `self-insert` *command
# name* intercepts nothing (verified), so each key is bound individually via
# its octal escape, which also sidesteps every shell-quoting problem.
_adaptive_bind_printable() {
  local i esc ch q spec
  # `printf -v` rather than `$(printf ...)`: command substitution forks a
  # subshell even for a builtin, and this loop runs for every printable
  # character on every shell startup.
  for (( i = 33; i < 127; i++ )); do
    printf -v esc '\\%03o' "$i"
    [[ $esc == '\\040' ]] && continue
    printf -v ch '%b' "$esc"
    printf -v q '%q' "$ch"
    printf -v spec '"%s": _adaptive_self_insert %s' "$esc" "$q"
    builtin bind -x "$spec" 2>/dev/null || true
  done
}

_adaptive_install() {
  # The engine answers Tab, and defers to everything else. `-D` is the
  # fallback slot and `-E` the empty-command slot; registering them does not
  # displace bash-completion's own per-command functions.
  builtin complete -D -F _adaptive_complete -o filenames 2>/dev/null || true
  builtin complete -E -F _adaptive_complete -o filenames 2>/dev/null || true

  _adaptive_bind_printable

  # Start on Bash's own accept-line; it only moves onto `_adaptive_enter`
  # while a suggestion is actually showing.
  _adaptive_arm

  # Tab and Shift-Tab both go through the drop-the-suggestion macro from the
  # very start.
  _adaptive_detect_browse
  _adaptive_bindx "$ADAPTIVE_TAB_DROP_KEY" '_adaptive_pre_complete'
  builtin bind -x "$_ADAPTIVE_BINDING" 2>/dev/null || true
  _adaptive_bindx "$ADAPTIVE_BROWSE_MARK_KEY" '_adaptive_pre_complete'
  builtin bind -x "$_ADAPTIVE_BINDING" 2>/dev/null || true
  _adaptive_arm_tab
  _adaptive_arm_browse

  printf -v _spec '"%s": _adaptive_self_insert %q' '\\040' ' '
  builtin bind -x "$_spec" 2>/dev/null || true

  builtin bind -x '"\C-h": _adaptive_backspace' 2>/dev/null || true
  builtin bind -x '"\C-w": _adaptive_backspace' 2>/dev/null || true
  builtin bind -x '"\C-u": _adaptive_kill_to_start' 2>/dev/null || true
  builtin bind -x '"\C-k": _adaptive_kill_to_end' 2>/dev/null || true
  builtin bind -x '"\C-a": _adaptive_move_start' 2>/dev/null || true
  builtin bind -x '"\e[D": _adaptive_move_left' 2>/dev/null || true
  builtin bind -x '"\C-b": _adaptive_move_left' 2>/dev/null || true
  _adaptive_bindx "$ADAPTIVE_GHOST_ACCEPT_KEY" '_adaptive_accept'
  builtin bind -x "$_ADAPTIVE_BINDING" 2>/dev/null || true
  # End accepts too, but only replaces End's own behaviour while a suggestion
  # is on screen, so ordinary end-of-line is untouched.
  builtin bind -x '"\e[F": _adaptive_accept_end' 2>/dev/null || true
  builtin bind -x '"\e[4~": _adaptive_accept_end' 2>/dev/null || true
  builtin bind -x '"\e[H": _adaptive_move_start' 2>/dev/null || true
  builtin bind -x '"\eOH": _adaptive_move_start' 2>/dev/null || true
  _adaptive_bindx "$ADAPTIVE_GHOST_WORD_KEY" '_adaptive_accept_word'
  builtin bind -x "$_ADAPTIVE_BINDING" 2>/dev/null || true
  _adaptive_bindx "$ADAPTIVE_GHOST_REJECT_KEY" '_adaptive_toggle_suppress'
  builtin bind -x "$_ADAPTIVE_BINDING" 2>/dev/null || true

  # Shift-Tab. Bound from ADAPTIVE_BROWSE_KEY rather than assuming the
  # terminal sends the usual ESC [ Z; `adaptive doctor` can confirm what this
  # terminal actually emits.
  _adaptive_arm_browse
}

_adaptive_install

# ---------------------------------------------------------------------------
# history
# ---------------------------------------------------------------------------

# Bash has no preexec hook, so the line just accepted is recovered from Bash's
# own history when the next prompt is drawn. History is authoritative about
# what was actually run, which is exactly what the engine should learn from.
_adaptive_history_hook() {
  local line
  line=$(HISTTIMEFORMAT= builtin history 1 2>/dev/null) || return 0
  line=${line#*  }
  [[ -n $line ]] || return 0
  [[ $line == "${_ADAPTIVE_SEEN_HISTORY:-}" ]] && return 0
  _ADAPTIVE_SEEN_HISTORY=$line
  _adaptive_history_record "$line"
  return 0
}

# Fold this shell's existing history into the usage profile once, so day-one
# predictions already reflect real habits.
_adaptive_history_import
_ADAPTIVE_SEEN_HISTORY=$(HISTTIMEFORMAT= builtin history 1 2>/dev/null)
_ADAPTIVE_SEEN_HISTORY=${_ADAPTIVE_SEEN_HISTORY#*  }

# Append to PROMPT_COMMAND without disturbing what is there, and without
# leaving a duplicate if this file is sourced twice.
if [[ ${PROMPT_COMMAND:-} != *_adaptive_history_hook* ]]; then
  if [[ -z ${PROMPT_COMMAND:-} ]]; then
    PROMPT_COMMAND='_adaptive_history_hook'
  else
    PROMPT_COMMAND="${PROMPT_COMMAND%;};_adaptive_history_hook"
  fi
fi